package net.civeira.phylax.features.document.themeversion.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.document.themeversion.domain.ThemeVersion;
import net.civeira.phylax.features.document.themeversion.domain.gateway.ThemeVersionCursor;
import net.civeira.phylax.features.document.themeversion.domain.gateway.ThemeVersionFilter;

class ThemeVersionSlider extends Slider<ThemeVersion> {

  /**
   * @autogenerated SlideGenerator
   */
  private final ThemeVersionCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final ThemeVersionFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<ThemeVersionFilter, ThemeVersionCursor, Iterator<ThemeVersion>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  ThemeVersionSlider(final Iterator<ThemeVersion> multi, final int limit,
      final BiFunction<ThemeVersionFilter, ThemeVersionCursor, Iterator<ThemeVersion>> gateway,
      final ThemeVersionFilter filter, final ThemeVersionCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param themeVersions
   * @param limit
   * @return
   */
  @Override
  public Iterator<ThemeVersion> next(List<ThemeVersion> themeVersions, int limit) {
    ThemeVersion last = themeVersions.get(themeVersions.size() - 1);
    ThemeVersionCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
